import itertools

def count_good_paths(grid):
    rows = len(grid)
    cols = len(grid[0])
    dp = [[0] * cols for _ in range(rows)]

    # To compute dp, we need to process fields in increasing order of their values
    fields = []
    for r in range(rows):
        for c in range(cols):
            fields.append((grid[r][c], r, c))
    fields.sort()

    for val, r, c in fields:
        neighbors = []
        if r > 0: neighbors.append((r-1, c))
        if r < rows - 1: neighbors.append((r+1, c))
        if c > 0: neighbors.append((r, c-1))
        if c < cols - 1: neighbors.append((r, c+1))

        smaller_neighbors = []
        all_neighbors_larger = True
        for nr, nc in neighbors:
            if grid[nr][nc] < val:
                smaller_neighbors.append((nr, nc))
            else:
                all_neighbors_larger = False

        if all_neighbors_larger:
            dp[r][c] = 1
        else:
            res = 0
            for nr, nc in smaller_neighbors:
                res += dp[nr][nc]
            dp[r][c] = res

    return sum(sum(row) for row in dp)

