def count_good_paths(board):
    n = len(board)
    m = len(board[0])

    # Find S
    S = []
    for r in range(n):
        for c in range(m):
            val = board[r][c]
            is_S = True
            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < m:
                    if board[nr][nc] < val:
                        is_S = False
                        break
            if is_S:
                S.append((r, c))

    # dp(r, c) = 1 + sum(dp(nr, nc) for (nr, nc) in N+(r, c))
    # We can compute this by iterating through values in decreasing order
    dp = [[0] * m for _ in range(n)]
    values = []
    for r in range(n):
        for c in range(m):
            values.append((board[r][c], r, c))
    values.sort(reverse=True)

    for val, r, c in values:
        res = 1
        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < m:
                if board[nr][nc] > val:
                    res += dp[nr][nc]
        dp[r][c] = res

    total = 0
    for r, c in S:
        total += dp[r][c]
    return total

