        is_local_min = True
        for nr, nc in neighbors:
            if grid[nr][nc] < val:
                is_local_min = False
                smaller_neighbors.append((nr, nc))
        if is_local_min:
            dp[r][c] = 1
        else:
            res = 0
            for nr, nc in smaller_neighbors:
                res += dp[nr][nc]
            dp[r][c] = res
    return sum(sum(row) for row in dp)

def solve_min_paths(rows, cols):
    min_paths = float('inf')
    for p in itertools.permutations(range(1, rows*cols + 1)):
        grid = [p[i*cols : (i+1)*cols] for i in range(rows)]
        count = count_good_paths(grid)
        if count < min_paths:
            min_paths = count
    return min_paths

